package fraymus.workspace;

import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TaskCost090Test {
    static JSONObject spec(){return TaskCost080Test.spec(0);}
    static JSONObject model(){var m=TaskCost089Test.model().put("code","same-code").put("createdAt","2026-11-07T00:00:00Z");
        int i=0;for(Object raw:m.getJSONArray("pairs")){var p=(JSONObject)raw;var s=spec();if(i++>=3)s.getJSONArray("targets").getJSONObject(0).getJSONArray("positionM").put(0,s.getJSONArray("targets").getJSONObject(0).getJSONArray("positionM").getDouble(0)+.01);p.put("spec",s);}return m;}
    static JSONObject candidate(){return TaskCost085Test.candidate();}
    static JSONObject decision(){return TaskCost089.choose(spec(),"calibrated",new JSONArray().put(candidate()),TaskCost080Test.workload(),model(),TaskCost085Test.ID,1,"paired089");}
    static JSONObject outcome(String id,double ms){var j=new JSONObject().put("bankSnapshot",new JSONArray().put(new JSONObject().put("id",TaskCost085Test.ID)));
        return TaskCost080Test.measured(id,"memory",ms,0).put("receiptId",TaskCost085Test.ID).put("jobSha256",WorldFrames.hash(j)).put("recordedAt","2026-11-07T01:00:00Z").put("clock089",TaskCost089.clock(TaskCost089Test.OWNER,0,(long)(ms*1e6)));}
    static JSONObject observation(String id,double ms){return TaskCost090.observation(outcome(id,ms),new JSONObject().put("bankSnapshot",new JSONArray().put(new JSONObject().put("id",TaskCost085Test.ID))),candidate(),model());}
    static double expected(){return decision().getJSONObject("cost080").getDouble("memoryMillis");}
    @Test public void emptyHistoryIsUnobservedNotFresh(){var d=TaskCost090.apply(spec(),decision(),new JSONArray());assertEquals("unobserved",d.getJSONObject("freshness090").getString("status"));assertTrue(d.getBoolean("useMemory"));}
    @Test public void oneSlowOutcomeDoesNotQuarantine(){var g=TaskCost090.guard(spec(),decision(),new JSONArray().put(observation("a",expected()*3)));assertFalse(g.getBoolean("blocked"));}
    @Test public void twoSlowOutcomesFallBackWithoutChangingEstimate(){var d=decision();var old=WorldFrames.copy(d.getJSONObject("cost080"));TaskCost090.apply(spec(),d,new JSONArray().put(observation("a",expected()*3)).put(observation("b",expected()*3)));assertFalse(d.getBoolean("useMemory"));assertEquals("direct",d.getString("preferred"));assertTrue(old.similar(d.getJSONObject("cost080")));assertEquals("suspect",d.getJSONObject("freshness090").getString("status"));}
    @Test public void fasterIsDriftToo(){assertTrue(TaskCost090.guard(spec(),decision(),new JSONArray().put(observation("a",1000)).put(observation("b",1000))).getBoolean("blocked"));}
    @Test public void OppositeDeviationsDoNotPretendToBeSameDirection(){assertFalse(TaskCost090.guard(spec(),decision(),new JSONArray().put(observation("a",1000)).put(observation("b",expected()*3))).getBoolean("blocked"));}
    @Test public void stableRepeatedOutcomesRemainEligible(){var a=new JSONArray();for(int i=0;i<3;i++)a.put(observation("a"+i,expected()+i));assertFalse(TaskCost090.guard(spec(),decision(),a).getBoolean("blocked"));}
    @Test public void strictThresholdBoundaryIsNotDrift(){var p=observation("a",expected());double tolerance=p.getDouble("toleranceMillis");assertEquals("within",observation("b",expected()+tolerance).getString("direction"));assertEquals("slower",observation("c",expected()+tolerance+1).getString("direction"));}
    @Test public void duplicateAndUnboundedObservationsRefused(){var o=observation("a",1000);assertThrows(IllegalArgumentException.class,()->TaskCost090.guard(spec(),decision(),new JSONArray().put(o).put(o)));assertThrows(IllegalArgumentException.class,()->TaskCost090.guard(spec(),decision(),new JSONArray().put(o).put(o).put(o).put(o)));}
    @Test public void fixedControlsAreUnchanged(){for(String mode:new String[]{"simple","memory"}){var d=decision().put("mode",mode);assertSame(d,TaskCost090.apply(spec(),d,new JSONArray()));assertFalse(d.has("freshness090"));}}
    @Test public void staticObstacleChangeRejectsSavings(){var s=spec();var o=s.getJSONObject("source").getJSONArray("objects").getJSONObject(0);o.getJSONArray("position").put(0,2);assertFalse(TaskCost090.nearby(spec(),s));assertEquals("outside-coverage",TaskCost090.guard(s,decision(),new JSONArray()).getString("status"));}
    @Test public void nearbySmallChangeAndIdenticalSceneAreSupported(){assertTrue(TaskCost090.nearby(spec(),spec()));var s=spec();s.getJSONArray("targets").getJSONObject(0).getJSONArray("positionM").put(0,s.getJSONArray("targets").getJSONObject(0).getJSONArray("positionM").getDouble(0)+.01);assertTrue(TaskCost090.nearby(spec(),s));}
    @Test public void roleGravitySizeAndOrientationChangesAreUncovered(){for(String field:new String[]{"role","gravity","size","rotation"}){var s=spec();var o=s.getJSONObject("source").getJSONArray("objects").getJSONObject(1);switch(field){case "role"->o.put("sourceId","unknown");case "gravity"->s.getJSONObject("source").put("gravityMps2",1);case "size"->o.getJSONArray("size").put(0,2);case "rotation"->o.put("rotation",WorldPlan.quat(90));}assertFalse(field,TaskCost090.nearby(spec(),s));}}
    @Test public void profileReceiptWorkloadColdAndOldEvidenceAreExcluded(){assertTrue(TaskCost090.eligible(outcome("recent",expected()),candidate(),spec(),TaskCost080Test.workload(),model()));for(String field:new String[]{"profile","receipt","workload","cold","time","code","ineligible"}){var c=outcome("recent",expected());switch(field){case "profile"->c.getJSONObject("profile").put("cpus",999);case "receipt"->c.put("receiptId","different");case "workload"->c.getJSONObject("workload").put("skill",true);case "cold"->c.put("warm",false);case "time"->c.put("recordedAt","2026-11-06T00:00:00Z");case "code"->c.put("code","old");case "ineligible"->c.put("eligible",false);}assertFalse(field,TaskCost090.eligible(c,candidate(),spec(),TaskCost080Test.workload(),model()));}}
    @Test public void fitMembersCannotLeakBackAsNewEvidence(){var m=model();assertFalse(TaskCost090.eligible(outcome(m.getJSONArray("pairs").getJSONObject(0).getString("memoryId"),expected()),candidate(),spec(),TaskCost080Test.workload(),m));}
    @Test public void changedDurationOrJobIsRefused(){var c=outcome("recent",expected());c.put("totalMillis",1);assertThrows(IllegalArgumentException.class,()->TaskCost090.observation(c,new JSONObject(),candidate(),model()));assertThrows(IllegalStateException.class,()->TaskCost090.observation(outcome("recent",expected()),new JSONObject(),candidate(),model()));}
    @Test public void newFitDoesNotInheritOldWarning(){var m=model().put("createdAt","2026-11-07T02:00:00Z");assertFalse(TaskCost090.eligible(outcome("a",1000),candidate(),spec(),TaskCost080Test.workload(),m));}
}
